    #[test]
    fn distinct_loss_pattern_counter_is_exact_within_its_budgets() {
        let mut counter = DistinctLossPatternCounter::default();
        counter.observe(&[1, 3]);
        counter.observe(&[1, 3]);
        counter.observe(&[2]);

        assert_eq!(counter.count(), 2);
        assert!(counter.is_exact());
    }

    #[test]
    fn distinct_loss_pattern_counter_does_not_retain_an_oversized_pattern() {
        let mut counter = DistinctLossPatternCounter::default();
        let pattern = vec![0; MAX_EXACT_LOSS_PATTERN_TERMS + 1];

        counter.observe(&pattern);

        assert_eq!(counter.count(), 1);
        assert!(!counter.is_exact());
        let DistinctLossPatternState::Approximate { registers } = &counter.state else {
            panic!("oversized pattern must switch to fixed-memory counting")
        };
        assert_eq!(registers.len(), LOSS_PATTERN_HLL_REGISTERS);
    }

    #[test]
    fn distinct_loss_pattern_counter_bounds_many_unique_patterns() {
        let mut counter = DistinctLossPatternCounter::default();
        let pattern_count = MAX_EXACT_LOSS_PATTERNS * 4;
        for pattern in 0..pattern_count {
            counter.observe(&[pattern]);
        }

        assert!(!counter.is_exact());
        assert!(counter.count().abs_diff(pattern_count) < pattern_count / 10);
        let DistinctLossPatternState::Approximate { registers } = &counter.state else {
            panic!("unique-pattern stream must switch to fixed-memory counting")
        };
        assert_eq!(registers.len(), LOSS_PATTERN_HLL_REGISTERS);
    }

    fn dataset_for(circuit_text: &str) -> Dataset {
        let instrs = rstim::validation::parse_and_validate(circuit_text).unwrap();
        let stats = rstim::stats::summarize(&instrs);
        Dataset {
            manifest: PublicManifest {
                schema_version: 1,
                dataset_id: None,
                mode: "measurements_blinded".to_string(),
                shots: 0,
                row: RowManifest {
                    kind: "measurements".to_string(),
                    bits: stats.num_measurements,
                    encoding: "b8".to_string(),
                    bit_order: "lsb_first".to_string(),
                    bytes_per_shot: stats.num_measurements.div_ceil(8),
                },
                circuit: CircuitManifest {
                    file: "circuit.stim".to_string(),
                    sha256: sha256_hex(circuit_text.as_bytes()),
                    measurements: stats.num_measurements,
                    detectors: stats.num_detectors,
                    observables: stats.num_observables,
                    sweep_bits: stats.num_sweep_bits,
                },
                shots_file: FileManifest {
                    file: "shots.b8".to_string(),
                    sha256: String::new(),
                    bits: stats.num_measurements,
                    bytes_per_shot: stats.num_measurements.div_ceil(8),
                },
            },
            circuit_text: circuit_text.to_string(),
            shots_path: PathBuf::new(),
        }
    }

    fn compiled(circuit_text: &str) -> CompiledCircuit {
        compile_circuit(&dataset_for(circuit_text), DecoderKind::EnvelopeMle).unwrap()
    }

    #[cfg(feature = "ilp")]
    fn observed(bits: &[u8]) -> Vec<usize> {
        bits.iter()
            .enumerate()
            .filter_map(|(index, &bit)| (bit != 0).then_some(index))
            .collect()
    }

    #[cfg(feature = "ilp")]
    fn mask(indices: &[usize]) -> u64 {
        indices.iter().fold(0, |value, &index| value | (1 << index))
    }

    fn singleton_syndrome(bits: &[u8]) -> LossAwareDetectorShot {
        LossAwareDetectorShot {
            lost_measurements: Vec::new(),
            detector_valid: vec![true; bits.len()],
            checks: bits
                .iter()
                .enumerate()
                .map(|(detector, &bit)| rstim::m2d::LossAwareDetectorCheck {
                    source_detectors: vec![detector],
                    value: bit != 0,
                })
                .collect(),
            canonical_detector_values: bits.iter().map(|&bit| bit != 0).collect(),
        }
    }

    #[cfg(feature = "ilp")]
    fn reference_effect(effect: &Effect) -> ReferenceEffect {
        ReferenceEffect {
            id: effect.id.clone(),
            detectors: effect.detectors.clone(),
            observables: effect.observables.clone(),
            weight: effect.weight,
        }
    }

    #[cfg(feature = "ilp")]
    fn reference_case(
        circuit: &CompiledCircuit,
        observed_detectors: Vec<usize>,
        losses: &[usize],
    ) -> AtomLossCase {
        AtomLossCase {
            schema_version: "atom-loss-envelope.v0".to_string(),
            num_detectors: circuit.loss_aware_m2d.layout().num_detectors(),
            num_observables: circuit.num_observables,
            observed_detectors,
            independent_effects: circuit
                .independent_effects
                .iter()
                .map(reference_effect)
                .collect(),
            loss_envelopes: losses
                .iter()
                .map(|&loss| ReferenceLossEnvelope {
                    loss_id: circuit.envelopes[loss].id.clone(),
                    candidates: circuit.envelopes[loss]
                        .candidates
                        .iter()
                        .map(reference_effect)
                        .collect(),
                })
                .collect(),
        }
    }

    #[cfg(feature = "ilp")]
    fn reference_mle(circuit: &CompiledCircuit, syndrome: &[u8], losses: &[usize]) -> u64 {
        let case = reference_case(circuit, observed(syndrome), losses);
        match decode_reference_mle(&case).unwrap() {
            DecodeOutcome::Optimal(result) => mask(&result.predicted_observables),
            DecodeOutcome::Infeasible(_) => panic!("reference MLE unexpectedly infeasible"),
        }
    }

    #[cfg(feature = "ilp")]
    fn project_reference_effect(
        effect: &ReferenceEffect,
        checks: &[rstim::m2d::LossAwareDetectorCheck],
    ) -> ReferenceEffect {
        ReferenceEffect {
            id: effect.id.clone(),
            detectors: checks
                .iter()
                .enumerate()
                .filter_map(|(row, check)| {
                    (check
                        .source_detectors
                        .iter()
                        .filter(|detector| effect.detectors.contains(detector))
                        .count()
                        % 2
                        == 1)
                        .then_some(row)
                })
                .collect(),
            observables: effect.observables.clone(),
            weight: effect.weight,
        }
    }

    #[cfg(feature = "ilp")]
    fn project_reference_case(
        canonical: &AtomLossCase,
        checks: &[rstim::m2d::LossAwareDetectorCheck],
    ) -> AtomLossCase {
        AtomLossCase {
            schema_version: canonical.schema_version.clone(),
            num_detectors: checks.len(),
            num_observables: canonical.num_observables,
            observed_detectors: checks
                .iter()
                .enumerate()
                .filter_map(|(row, check)| check.value.then_some(row))
                .collect(),
            independent_effects: canonical
                .independent_effects
                .iter()
                .map(|effect| project_reference_effect(effect, checks))
                .collect(),
            loss_envelopes: canonical
                .loss_envelopes
                .iter()
                .map(|envelope| ReferenceLossEnvelope {
                    loss_id: envelope.loss_id.clone(),
                    candidates: envelope
                        .candidates
                        .iter()
                        .map(|effect| project_reference_effect(effect, checks))
                        .collect(),
                })
                .collect(),
        }
    }

    #[cfg(feature = "ilp")]
    fn issue_679_native_reference_cases() -> (AtomLossCase, AtomLossCase, Vec<usize>, usize, usize)
    {
        let fixture = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/fixtures/current_rstim_atom_loss/midswap_canonical_mle");
        let dataset = read_dataset(&fixture).unwrap();
        let circuit = compile_circuit(&dataset, DecoderKind::EnvelopeMle).unwrap();
        let shots = File::open(&dataset.shots_path).unwrap();
        let mut reader = ResultBlockReader::new(
            BufReader::new(shots),
            dataset.manifest.row.bits,
            dataset.manifest.shots as u64,
            OutputFormat::B8,
            BATCH_SIZE,
        )
        .unwrap();
        let measurements = reader.next_block().unwrap().unwrap();
        let mut syndromes = circuit.loss_aware_syndromes(&measurements).unwrap();
        let losses = circuit.loss_patterns(&measurements).pop().unwrap();
        let syndrome = syndromes.pop().unwrap();
        let canonical = reference_case(
            &circuit,
            syndrome
                .canonical_detector_values
                .iter()
                .enumerate()
                .filter_map(|(detector, &value)| value.then_some(detector))
                .collect(),
            &losses,
        );
        let projected = project_reference_case(&canonical, &syndrome.checks);
        (
            canonical,
            projected,
            losses,
            syndrome.canonical_detector_values.len(),
            syndrome.checks.len(),
        )
    }

