                        .decode(&singleton_syndrome(syndrome), losses)
                        .unwrap(),
                )
            })
            .collect();
        assert_eq!(matching_predictions, reference_matching(&circuit, &shots));
        assert_eq!(matching_predictions, [1, 0, 0, 0]);
